<?php require 'config.php';require 'sipsn_lib.php';need(['admin','petugas']);sipsn_ensure();
$yrs=array_map('intval',array_column(q('SELECT DISTINCT tahun FROM waste_generation_sipsn ORDER BY tahun')->fetchAll(),'tahun'));$kabs=array_column(q('SELECT DISTINCT nama_kabkota FROM waste_generation_sipsn ORDER BY 1')->fetchAll(),'nama_kabkota');$pers=array_column(q('SELECT DISTINCT periode FROM waste_generation_sipsn ORDER BY 1')->fetchAll(),'periode');
if(!$yrs){admin_head('Analisis Data','ana');?><div class="card card-eco p-4 text-center"><h5>Belum ada data SIPSN</h5><p class="text-muted">Import dataset lewat halaman <a href="sipsn.php">Data Timbulan Sampah</a> atau jalankan <code>tools/sipsn.sql</code>.</p></div><?php admin_foot();exit;}
$yr=(int)($_GET['tahun']??0);if(!in_array($yr,$yrs,true))$yr=max($yrs);$kab=in_array($_GET['kab']??'',$kabs,true)?$_GET['kab']:'';$pr=in_array($_GET['periode']??'',$pers,true)?$_GET['periode']:'';$desc=($_GET['urut']??'desc')!='asc';
$fw='';$fp=[];if($kab){$fw.=' AND nama_kabkota=?';$fp[]=$kab;}if($pr!==''){$fw.=' AND periode=?';$fp[]=$pr;}
$T=q("SELECT tahun,SUM(jml_timbulan_harian) h,SUM(jml_timbulan_tahun) t,COUNT(DISTINCT nama_kabkota) n FROM waste_generation_sipsn WHERE 1=1$fw GROUP BY tahun ORDER BY tahun",$fp)->fetchAll();
$K=q("SELECT SUM(jml_timbulan_harian) h,SUM(jml_timbulan_tahun) t,COUNT(DISTINCT nama_kabkota) n FROM waste_generation_sipsn WHERE tahun=?$fw",array_merge([$yr],$fp))->fetch();
$rw='';$rp=[$yr];if($pr!==''){$rw=' AND periode=?';$rp[]=$pr;}
$R=q("SELECT nama_kabkota k,SUM(jml_timbulan_tahun) t,SUM(jml_timbulan_harian) h FROM waste_generation_sipsn WHERE tahun=?$rw GROUP BY nama_kabkota ORDER BY t DESC",$rp)->fetchAll();if(!$desc)$R=array_reverse($R);
$Y=[];foreach($yrs as $y)if(in_array($y+1,$yrs,true)){$c=q("SELECT COUNT(*) n,SUM(a.jml_timbulan_tahun) a,SUM(b.jml_timbulan_tahun) b FROM waste_generation_sipsn a JOIN waste_generation_sipsn b ON b.nama_kabkota=a.nama_kabkota AND b.periode=a.periode AND b.tahun=a.tahun+1 WHERE a.tahun=?".str_replace(['nama_kabkota=?','periode=?'],['a.nama_kabkota=?','a.periode=?'],$fw),array_merge([$y],$fp))->fetch();if($c['n']>0&&$c['a']>0)$Y[]=['l'=>"{$y}→".($y+1),'p'=>round(($c['b']/$c['a']-1)*100,2),'n'=>(int)$c['n']];}
$I=sipsn_insights($yr);admin_head('Analisis Data','ana');?>
<form class="row g-2 mb-3" data-load><div class="col-6 col-md-2"><select class="form-select" name="tahun"><?php foreach($yrs as $y):?><option <?=$yr==$y?'selected':''?>><?=$y?></option><?php endforeach?></select></div><div class="col-6 col-md-4"><select class="form-select" name="kab"><option value="">Seluruh wilayah</option><?php foreach($kabs as $k):?><option <?=$kab===$k?'selected':''?>><?=e($k)?></option><?php endforeach?></select></div><div class="col-6 col-md-2"><select class="form-select" name="periode"><option value="">Semua periode</option><?php foreach($pers as $k):?><option <?=$pr===$k?'selected':''?>><?=e($k)?></option><?php endforeach?></select></div><div class="col-6 col-md-2"><select class="form-select" name="urut"><option value="desc">Tertinggi dulu</option><option value="asc" <?=$desc?'':'selected'?>>Terendah dulu</option></select></div><div class="col-md-2"><button class="btn btn-eco w-100">Terapkan</button></div></form>
<div class="row g-3 mb-3"><?php foreach([['Timbulan tahunan '.$yr,nf($K['t']),'bi-trash3',''],['Timbulan harian '.$yr,nf($K['h'],1),'bi-calendar-day','am'],['Kab/kota terdata '.$yr,(int)$K['n'],'bi-geo-alt','bl'],['Tahun data terbaru',max($yrs),'bi-clock-history','']] as $c):?><div class="col-6 col-lg-3"><div class="card card-eco p-3 kpi"><div class="ico <?=$c[3]?>"><i class="bi <?=$c[2]?>"></i></div><div><div class="stat"><?=$c[1]?></div><small class="text-muted"><?=$c[0]?></small></div></div></div><?php endforeach?></div>
<div class="row g-3 mb-3"><div class="col-lg-6"><div class="card card-eco p-3"><b>Tren timbulan per tahun<?=$kab?' &ndash; '.e($kab):''?></b><canvas id="c1" height="150"></canvas><small class="text-muted">Jumlah wilayah per tahun berbeda; arahkan kursor untuk melihat cakupan.</small></div></div>
<div class="col-lg-6"><div class="card card-eco p-3"><b>Perubahan tahun ke tahun (wilayah sebanding)</b><?php if($Y):?><canvas id="c4" height="150"></canvas><small class="text-muted">Hanya wilayah yang ada di kedua tahun; jumlahnya tertera di tooltip.</small><?php else:?><p class="text-muted my-4 text-center">Belum ada pasangan tahun berurutan untuk filter ini.</p><?php endif?></div></div>
<div class="col-lg-7"><div class="card card-eco p-3"><b>Peringkat kab/kota <?=$yr?></b><?php if($R):?><canvas id="c2" height="<?=max(120,count($R)*18)?>"></canvas><?php else:?><p class="text-muted my-4 text-center">Tidak ada data.</p><?php endif?><small class="text-muted">Dataset tanpa koordinat, jadi persebaran ditampilkan sebagai peringkat (bukan titik peta). <?=e(UNIT_NOTE)?></small></div></div>
<div class="col-lg-5"><div class="card card-eco p-3 mb-3"><b>Kontribusi terhadap total terdata <?=$yr?></b><?php if($R):?><canvas id="c3" height="200"></canvas><?php endif?></div><div class="card card-eco p-3"><b class="mb-2">Insight &amp; rekomendasi (berbasis data)</b><?php foreach($I as $i):?><div class="ins <?=$i[0]?>"><b><?=e($i[1])?></b><?=e($i[2])?></div><?php endforeach?></div></div></div>
<?php $col="['#14532D','#16A34A','#10B981','#F59E0B','#6EE7B7','#065F46','#FCD34D','#84CC16','#0EA5E9','#6B7280','#A3E635','#34D399','#047857','#FBBF24','#86EFAC']";
admin_foot("const T=".json_encode($T).",R=".json_encode($R).",Y=".json_encode($Y).",C=$col;
new Chart(c1,{type:'line',data:{labels:T.map(x=>x.tahun),datasets:[{label:'Harian',data:T.map(x=>+x.h),yAxisID:'y',borderColor:'#16A34A',tension:.3},{label:'Tahunan',data:T.map(x=>+x.t),yAxisID:'y1',borderColor:'#F59E0B',tension:.3}]},options:{scales:{y:{title:{display:true,text:'Harian'}},y1:{position:'right',grid:{drawOnChartArea:false},title:{display:true,text:'Tahunan'}}},plugins:{tooltip:{callbacks:{afterLabel:c=>T[c.dataIndex].n+' kab/kota terdata'}}}}});
if(Y.length)new Chart(c4,{type:'bar',data:{labels:Y.map(x=>x.l),datasets:[{label:'Perubahan (%)',data:Y.map(x=>x.p),backgroundColor:Y.map(x=>x.p>=0?'#F59E0B':'#16A34A')}]},options:{plugins:{legend:{display:false},tooltip:{callbacks:{afterLabel:c=>Y[c.dataIndex].n+' wilayah sebanding'}}}}});
if(R.length){new Chart(c2,{type:'bar',data:{labels:R.map(x=>x.k),datasets:[{label:'Timbulan tahunan',data:R.map(x=>+x.t),backgroundColor:'#16A34A'}]},options:{indexAxis:'y',plugins:{legend:{display:false}}}});
new Chart(c3,{type:'doughnut',data:{labels:R.map(x=>x.k),datasets:[{data:R.map(x=>+x.t),backgroundColor:C}]},options:{plugins:{legend:{position:'right',labels:{boxWidth:10,font:{size:10}}}}}});}");
